import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ page, signIn }) => {
  // Arrange
  await signIn("member");

  // Act
  const response = await page.request.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, "logout sends a Set-Cookie for the session").toBeDefined();
  const [pair, ...attributes] = cookie!.value.split(";").map((part) => part.trim());
  // The value may be serialized empty as `session=` or as `session=""`; both are an emptied cookie.
  const value = pair.slice("session=".length).replace(/^"(.*)"$/, "$1");
  expect(value, "the session cookie value is emptied").toBe("");
  const cleared =
    attributes.some((a) => /^max-age=0$/i.test(a)) ||
    attributes.some((a) => /^expires=thu, 01 jan 1970/i.test(a));
  expect(cleared, `session cookie expires immediately: ${cookie!.value}`).toBe(true);
});
